@startuml

class Museum {
  + Name : string
}

class Location {
  + Name : string
}

class Exhibition {
  + Title : string
  + OpeningDate : date
}

class ExhibitionItem {
  + Description : string
}

class Piece {
  + Description : string
}

class Collector {
  + Name : string
}

class Employee {
  + Name : string
}

Museum "1" -- "*" Location
Location "1" -- "*" Exhibition
Exhibition "*" -- "1" Employee : coordinator
Exhibition "1" -- "*" ExhibitionItem
ExhibitionItem "*" -- "0..*" Piece
ExhibitionItem "*" -- "1" Collector : requested from
Piece "*" -- "1" Collector : belongs to
Employee "0..1" -- "0..*" Employee : coach

@enduml

